//! Comparison against dftd4 4.3.1 and tblite 0.8.0 reference data generated by
//! `scripts/make_fixtures.py`. Run with `--nocapture` to see the deviations.

use axtb_d4::{ChargeModel, D4Dispersion, D4Model, RationalDamping, RealspaceCutoff};
use std::collections::HashMap;
use std::path::PathBuf;

struct Fixture {
    name: String,
    rec: HashMap<String, Vec<f64>>,
    numbers: Vec<usize>,
    positions: Vec<[f64; 3]>,
}

fn load_fixtures() -> Vec<Fixture> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests").join("fixtures");
    let mut paths: Vec<_> = std::fs::read_dir(&dir)
        .expect("fixture directory")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().map(|e| e == "txt").unwrap_or(false))
        .collect();
    paths.sort();
    let mut out = Vec::new();
    for p in paths {
        let text = std::fs::read_to_string(&p).unwrap();
        let mut rec: HashMap<String, Vec<f64>> = HashMap::new();
        let mut numbers = Vec::new();
        for line in text.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            let mut it = line.split_whitespace();
            let key = it.next().unwrap().to_string();
            if key == "numbers" {
                numbers = it.map(|t| t.parse::<usize>().unwrap()).collect();
            } else {
                rec.insert(key, it.map(|t| t.parse::<f64>().unwrap()).collect());
            }
        }
        let positions = rec["positions"].chunks(3).map(|c| [c[0], c[1], c[2]]).collect();
        out.push(Fixture { name: p.file_stem().unwrap().to_string_lossy().into_owned(), rec, numbers, positions });
    }
    assert!(!out.is_empty(), "no fixtures found");
    out
}

/// max |a-b| / max |b|
fn rel_max(a: &[f64], b: &[f64]) -> f64 {
    assert_eq!(a.len(), b.len());
    let scale = b.iter().fold(0.0f64, |m, x| m.max(x.abs()));
    let d = a.iter().zip(b).fold(0.0f64, |m, (x, y)| m.max((x - y).abs()));
    if scale == 0.0 {
        d
    } else {
        d / scale
    }
}

/// max_i |a_i-b_i| / |b_i| over entries with |b_i| > tiny * max|b|
fn rel_elem(a: &[f64], b: &[f64]) -> f64 {
    let scale = b.iter().fold(0.0f64, |m, x| m.max(x.abs()));
    a.iter().zip(b).filter(|(_, y)| y.abs() > 1e-10 * scale).fold(0.0f64, |m, (x, y)| m.max(((x - y) / y).abs()))
}

fn cutoff_of(v: &[f64]) -> RealspaceCutoff {
    RealspaceCutoff { disp2: v[0], disp3: v[1], cn: v[2], width2: v[3], width3: v[4] }
}

#[test]
fn compare_with_dftd4_and_tblite() {
    let fixtures = load_fixtures();
    let mut worst: HashMap<&'static str, f64> = HashMap::new();
    let mut note = |k: &'static str, v: f64| {
        let e = worst.entry(k).or_insert(0.0);
        *e = e.max(v);
    };
    eprintln!(
        "{:<17} {:>4} {:>9} {:>9} {:>9} {:>9} | {:>9} {:>9} {:>9} {:>9} | {:>9} {:>9} {:>9}",
        "molecule",
        "nat",
        "cn",
        "c6(el)",
        "alpha",
        "e(d4)",
        "e(tbcut)",
        "e(wide)",
        "e2/e3",
        "grad",
        "tblite.e3",
        "abs",
        "tb.scc.e2"
    );
    for fx in &fixtures {
        let nat = fx.numbers.len();
        let q = &fx.rec["d4.q"];
        let model = D4Model::new(&fx.numbers, ChargeModel::Eeq).unwrap();

        let mut cn = vec![0.0; nat];
        model.coordination_numbers(&fx.positions, 30.0, &mut cn);
        let e_cn = rel_elem(&cn, &fx.rec["d4.cn"]);
        note("cn", e_cn);

        let w = model.weight_references(&cn, q);
        let c6 = model.atomic_c6(&w);
        let e_c6 = rel_elem(&c6.c6, &fx.rec["d4.c6"]);
        note("c6", e_c6);
        let (alpha, _, _) = model.polarizabilities(&w);
        let e_alpha = rel_elem(&alpha, &fx.rec["d4.alpha"]);
        note("alpha", e_alpha);

        let mut e_sets = HashMap::new();
        let mut e_split: f64 = 0.0;
        let mut e_grad: f64 = 0.0;
        for set in ["dftd4", "tbcut", "wide"] {
            let disp =
                D4Dispersion::new(model.clone(), RationalDamping::GFN2, cutoff_of(&fx.rec[&format!("{set}.cutoff")]));
            let cache = disp.update(&fx.positions);
            let e2 = disp.energy_total(&cache, q);
            let mut e3a = vec![0.0; nat];
            let mut g = vec![[0.0; 3]; nat];
            disp.three_body(&cache, &mut e3a, Some(&mut g), false);
            let e3: f64 = e3a.iter().sum();
            let r2 = fx.rec[&format!("{set}.e2")][0];
            let r3 = fx.rec[&format!("{set}.e3")][0];
            let rt = fx.rec[&format!("{set}.e")][0];
            e_split = e_split.max(((e2 - r2) / r2).abs()).max(((e3 - r3) / r3).abs());
            e_sets.insert(set, ((e2 + e3 - rt) / rt).abs());

            // gradient: fixed-charge gradient + (dE/dq) (dq/dR) == dftd4 gradient
            disp.gradient(&cache, q, &mut g);
            // also exercise the convenience driver against the parts
            let mut ee = vec![0.0; nat];
            let mut gg = vec![[0.0; 3]; nat];
            let etot = disp.engrad_fixed_charges(&fx.positions, q, &mut ee, Some(&mut gg));
            assert!(((etot - (e2 + e3)) / rt).abs() < 1e-13);
            assert!(rel_max(gg.as_flattened(), g.as_flattened()) < 1e-13);
            if let Some(dqdr) = fx.rec.get("dqdr") {
                let mut vat = vec![0.0; nat];
                disp.potential(&cache, q, &mut vat, false);
                let mut gt = g.clone();
                for i in 0..nat {
                    for x in 0..3 {
                        for j in 0..nat {
                            gt[i][x] += vat[j] * dqdr[(i * 3 + x) * nat + j];
                        }
                    }
                }
                e_grad = e_grad.max(rel_max(gt.as_flattened(), &fx.rec[&format!("{set}.grad")]));
            }
        }
        note("e.dftd4", e_sets["dftd4"]);
        note("e.tblite_cutoffs", e_sets["tbcut"]);
        note("e.wide_smoothing", e_sets["wide"]);
        note("e2/e3 split", e_split);
        note("grad(+dq/dR)", e_grad);

        let (mut e_tb, mut a_tb) = (f64::NAN, f64::NAN);
        if let Some(r) = fx.rec.get("tblite_gfn2.e3") {
            let disp = D4Dispersion::gfn2(&fx.numbers).unwrap();
            let cache = disp.update(&fx.positions);
            let mut e3 = vec![0.0; nat];
            disp.three_body(&cache, &mut e3, None, false);
            let e3: f64 = e3.iter().sum();
            e_tb = ((e3 - r[0]) / r[0]).abs();
            a_tb = (e3 - r[0]).abs();
            note("tblite.e3 (14 digits printed)", e_tb);
        }
        let mut e_scc = f64::NAN;
        if let (Some(q), Some(r)) = (fx.rec.get("tblite_gfn2.q"), fx.rec.get("tblite_gfn2.e2_hf")) {
            let disp = D4Dispersion::gfn2(&fx.numbers).unwrap();
            let cache = disp.update(&fx.positions);
            let e2 = disp.energy_total(&cache, q);
            e_scc = ((e2 - r[0]) / r[0]).abs();
            note("tblite SCC e2 (Hellmann-Feynman FD)", e_scc);
        }
        eprintln!(
            "{:<17} {:>4} {:>9.2e} {:>9.2e} {:>9.2e} {:>9.2e} | {:>9.2e} {:>9.2e} {:>9.2e} {:>9.2e} | {:>9.2e} {:>9.2e} {:>9.2e}",
            fx.name, nat, e_cn, e_c6, e_alpha, e_sets["dftd4"], e_sets["tbcut"], e_sets["wide"],
            e_split, e_grad, e_tb, a_tb, e_scc
        );
    }
    let mut keys: Vec<_> = worst.iter().collect();
    keys.sort_by(|a, b| a.0.cmp(b.0));
    for (k, v) in keys {
        eprintln!("worst {k:<30} {v:.3e}");
    }
    assert!(worst["cn"] < 1e-12);
    assert!(worst["c6"] < 1e-12);
    assert!(worst["alpha"] < 1e-12);
    assert!(worst["e.dftd4"] < 1e-12);
    assert!(worst["e.tblite_cutoffs"] < 1e-12);
    assert!(worst["e.wide_smoothing"] < 1e-12);
    assert!(worst["e2/e3 split"] < 1e-12);
    // limited by the finite-difference dq/dR of the EEQ charges
    assert!(worst["grad(+dq/dR)"] < 1e-8);
    // tblite prints 14 significant digits
    assert!(worst["tblite.e3 (14 digits printed)"] < 1e-12);
    // limited by SCF convergence and the finite difference in lambda
    assert!(worst["tblite SCC e2 (Hellmann-Feynman FD)"] < 1e-8);
}

/// Finite-difference check of the fixed-charge gradient and the charge
/// potential on the 97 bohr long alkane, where all real-space cutoffs bite.
#[test]
fn alkane_finite_differences_with_cutoffs() {
    let fx = load_fixtures().into_iter().find(|f| f.name == "alkane_c40").unwrap();
    let nat = fx.numbers.len();
    let q: Vec<f64> = fx.rec["d4.q"].clone();
    for (qm, cut) in [(ChargeModel::Gfn2, RealspaceCutoff::TBLITE_GFN2), (ChargeModel::Eeq, RealspaceCutoff::DFTD4)] {
        let disp = D4Dispersion::new(D4Model::new(&fx.numbers, qm).unwrap(), RationalDamping::GFN2, cut);
        let etot = |p: &[[f64; 3]], q: &[f64]| {
            let mut e = vec![0.0; nat];
            disp.engrad_fixed_charges(p, q, &mut e, None)
        };
        let mut e = vec![0.0; nat];
        let mut g = vec![[0.0; 3]; nat];
        disp.engrad_fixed_charges(&fx.positions, &q, &mut e, Some(&mut g));
        let cache = disp.update(&fx.positions);
        let mut vat = vec![0.0; nat];
        disp.potential(&cache, &q, &mut vat, false);
        let h = 1e-3;
        let (mut dg, mut gmax, mut dv, mut vmax) = (0.0f64, 0.0f64, 0.0f64, 0.0f64);
        for i in [0usize, 1, 20, 39, 40, 41, 80, 120, 121] {
            for x in 0..3 {
                let f = |s: f64| {
                    let mut p = fx.positions.clone();
                    p[i][x] += s * h;
                    etot(&p, &q)
                };
                let fd = (f(-2.0) - 8.0 * f(-1.0) + 8.0 * f(1.0) - f(2.0)) / (12.0 * h);
                dg = dg.max((fd - g[i][x]).abs());
                gmax = gmax.max(g[i][x].abs());
            }
            let fq = |s: f64| {
                let mut qq = q.clone();
                qq[i] += s * 1e-4;
                disp.energy_total(&cache, &qq)
            };
            let fd = (fq(-2.0) - 8.0 * fq(-1.0) + 8.0 * fq(1.0) - fq(2.0)) / (12.0 * 1e-4);
            dv = dv.max((fd - vat[i]).abs());
            vmax = vmax.max(vat[i].abs());
        }
        eprintln!(
            "alkane {qm:?}: gradient max |fd - analytic| {dg:.2e} (max |g| {gmax:.2e}), potential {dv:.2e} (max |V| {vmax:.2e})"
        );
        assert!(dg < 1e-9 * gmax);
        assert!(dv < 1e-9 * vmax);
    }
}

#[test]
fn trivial_systems() {
    let disp = D4Dispersion::gfn2(&[]).unwrap();
    let cache = disp.update(&[]);
    assert_eq!(disp.energy_total(&cache, &[]), 0.0);
    let disp = D4Dispersion::gfn2(&[54]).unwrap();
    let cache = disp.update(&[[0.0; 3]]);
    let mut e = [0.0];
    let mut g = [[0.0; 3]];
    disp.three_body(&cache, &mut e, Some(&mut g), false);
    disp.gradient(&cache, &[0.1], &mut g);
    assert_eq!(e[0], 0.0);
    assert_eq!(g[0], [0.0; 3]);
}
